/* 组件就绪后执行 */
Eam.registerInit(async function(){
/* 控制列表与表单；页面结构由各独立HTML提供。 */
await (async()=>{const kind=document.body.dataset.problemKind,$=id=>document.getElementById(id);if(!$('problem-rows'))return;
const api=EamProblemApi,labels={draft:'草稿',submitted:'待分诊',triaged:'已分诊',archived:'已归档',open:'待处置',in_progress:'处置中',pending_verification:'待验证',closed:'已关闭',confirmed:'故障已确认',restored:'已恢复待复核',high:'高',medium:'中',low:'低'};
const pages={discoveries:'abnormal-events',defects:'defect-list',failures:'failure-events',hazards:'hazards'},names={discoveries:'异常发现',defects:'缺陷',failures:'故障',hazards:'隐患'};
let rows=[],audit=[],equipment=[],people=[],page=1,current=null,currentAction='',token=0,busy=false,actionToken=0,actionTarget=null;const query=new URLSearchParams(location.search),preferred=query.get('problemKind');const person=id=>people.find(p=>p.id===id)?.name||id||'未分配';
const badge=x=>{const span=document.createElement('span');span.className='problem-badge';span.dataset.state=x;span.textContent=labels[x]||x;return span;};
const canManage=()=>['engineer','supervisor'].includes(Eam.s.role);const terminal=r=>['closed','archived','void'].includes(r.status);
const overdue=r=>r.dueAt&&!terminal(r)&&new Date(r.dueAt+'T23:59:59+08:00')<new Date();
function actionFor(r){if(kind==='discoveries'&&r.status==='submitted'&&canManage())return ['triage','核实分诊'];if(kind==='defects'&&['open','in_progress'].includes(r.status)&&(canManage()||Eam.s.person===r.ownerId||Eam.s.role==='technician'))return ['submit','提交验证'];if(kind==='failures'&&r.status==='confirmed'&&(canManage()||Eam.s.role==='technician'))return ['restore','记录恢复'];if(['pending_verification','restored'].includes(r.status)&&canManage()&&r.executorId!==Eam.s.person)return ['verify',kind==='failures'?'复核故障':'独立验证'];return null;}
function draw(){const filtered=rows.filter(r=>(!$('search').value||[r.id,r.description,r.part].join(' ').toLowerCase().includes($('search').value.toLowerCase()))&&(!$('status-filter').value||r.status===$('status-filter').value)&&(!$('priority-filter').value||r.priority===$('priority-filter').value)&&(!$('mine').checked||r.ownerId===Eam.s.person));const totalPages=Math.max(1,Math.ceil(filtered.length/8));page=Math.min(page,totalPages);$('problem-rows').replaceChildren();for(const r of filtered.slice((page-1)*8,page*8)){const tr=document.createElement('tr');const values=[null,null,r.priority,r.status,person(r.ownerId),null,null];for(let i=0;i<values.length;i++){const td=document.createElement('td');td.dataset.label=['编号 / 现象','设备 / 部位','优先级','状态','责任人','发生 / 截止','操作'][i];if(i===0){const button=document.createElement('button');button.className='row-link';const strong=document.createElement('strong');strong.textContent=r.id;const name=document.createElement('span');name.textContent=r.description;button.append(strong,name);button.onclick=()=>openDetail(r.id);td.append(button);}else if(i===1){td.textContent=equipment.find(e=>e.id===r.equipmentId)?.name||r.equipmentId;const small=document.createElement('small');small.textContent=r.part;td.append(small);}else if(i===2||i===3)td.append(badge(values[i]));else if(i===5){td.textContent=EamProduct.time(r.occurredAt);const small=document.createElement('small');small.textContent=r.dueAt?'截止 '+r.dueAt+(overdue(r)?' · 已超期':''):r.source||'未设置期限';td.append(small);}else if(i===6){const a=actionFor(r);const button=document.createElement('button');button.textContent=a?a[1]:'查看';button.onclick=()=>a?openAction(r,a):openDetail(r.id);td.append(button);if(a){const view=document.createElement('button');view.textContent='详情';view.onclick=()=>openDetail(r.id);td.append(view);}if(kind!=='discoveries'&&r.status!=='closed'&&canManage()){const create=document.createElement('button');create.textContent='创建工单';create.onclick=()=>Eam.go('order-list',{create:'1',problemKind:kind,problemId:r.id});td.append(create);}if(kind==='discoveries'&&['submitted','triaged'].includes(r.status)&&canManage()){const archive=document.createElement('button');archive.textContent='归档';archive.onclick=()=>openAction(r,['archive','核实并归档']);td.append(archive);}}else td.textContent=values[i];tr.append(td);} $('problem-rows').append(tr);}
$('empty-state').hidden=!!filtered.length;$('metric-total').textContent=rows.length;$('metric-pending').textContent=rows.filter(r=>!terminal(r)&&r.status!=='triaged').length;$('metric-high').textContent=rows.filter(r=>r.priority==='high'&&!terminal(r)).length;$('metric-overdue').textContent=rows.filter(overdue).length;$('page-count').textContent=EamUiComponents.paginationText(filtered.length,page,totalPages);$('previous').disabled=page===1;$('next').disabled=page===totalPages;EamUiComponents.pagination($('page-count').parentElement,{page,pages:totalPages,total:filtered.length,pageSize:8,countId:'page-count',previousId:'previous',nextId:'next',onChange:nextPage=>{page=nextPage;draw();}});EamUiComponents.syncTableState($('problem-rows').closest('table'));}
async function load(){EamUiComponents.setTableStatus('problem-rows','loading');const t=++token;$('load-status').textContent='正在读取…';$('problem-rows').setAttribute('aria-busy','true');$('problem-rows').inert=true;try{const result=await api.request('GET','/'+kind);if(t!==token)return;rows=EamArchiveContext.filter(result.rows,location.search);audit=result.audit;draw();$('load-status').textContent='已读取 · '+rows.length+'条范围记录';EamUiComponents.setTableStatus('problem-rows',rows.length?'loaded':'empty',$('load-status').textContent);}catch(e){$('load-status').textContent=e.message+'，可点击刷新重试';$('problem-rows').replaceChildren();EamUiComponents.setTableStatus('problem-rows','error',e.message,load);}finally{if(t===token){$('problem-rows').removeAttribute('aria-busy');$('problem-rows').inert=false;}}}
async function openDetail(id){try{current=await api.request('GET','/'+kind+'/'+id);EamArchiveContext.assertRecord(current,location.search);const r=current;$('detail-id').textContent=r.id+' · 版本 '+r.version;$('detail-title').textContent=r.description;$('detail-status').replaceChildren(badge(r.status),badge(r.priority));$('detail-facts').replaceChildren();for(const [name,value]of [['设备',equipment.find(e=>e.id===r.equipmentId)?.name],['部位',r.part],['责任人',person(r.ownerId)],['发生时间',EamProduct.time(r.occurredAt)],['处置期限',r.dueAt||'未设置'],['来源',r.source||names[kind]],['失效模式',r.failureMode],['功能影响',r.impact],['恢复时间',r.restoredAt&&EamProduct.time(r.restoredAt)],['恢复耗时',r.restoredAt&&Math.round((Date.parse(r.restoredAt)-Date.parse(r.occurredAt))/60000)+'分钟']]){if(value===undefined||value===false)continue;const div=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value;div.append(dt,dd);$('detail-facts').append(div);}
$('detail-evidence').textContent=[r.evidence,r.triageReason&&'分诊依据：'+r.triageReason,r.emergencyAction&&'紧急控制：'+r.emergencyAction,r.verification&&'验证：'+r.verification.reason+' / '+r.verification.evidence].filter(Boolean).join('\n')||'暂无证据记录';$('detail-links').replaceChildren();for(const l of r.links||[]){const button=document.createElement('button');button.textContent=names[l.kind]+' '+l.id;button.onclick=()=>Eam.go(pages[l.kind],{id:l.id});$('detail-links').append(button);}if(!r.links?.length)$('detail-links').textContent='暂无关联记录';$('detail-audit').replaceChildren();const events=audit.filter(e=>e.objectId===r.id);for(const event of events){const div=document.createElement('div');div.className='problem-audit-row';div.textContent=EamProduct.time(event.at)+' · '+person(event.actorId)+' · '+(({create:'提交发现',archive:'归档发现',triage:'核实分诊',submit:'提交验证',restore:'记录恢复',verify:'独立验证',accept_linked:'技术验收送验证','apply-approval-result_linked':'终止审批生效并转交责任'})[event.action]||event.action||'未记录操作')+' · '+event.reason;if(event.after){const details=document.createElement('details'),summary=document.createElement('summary'),evidence=document.createElement('p');summary.textContent='查看本次证据快照';evidence.className='problem-evidence';evidence.textContent=[event.before&&'操作前：'+(event.before.evidence||'暂无证据'),event.before?.restoredAt&&'先前恢复声明：'+EamProduct.time(event.before.restoredAt),'操作后：'+(event.after.evidence||'暂无证据'),event.after.verification&&'验证记录：'+event.after.verification.reason+' / '+event.after.verification.evidence].filter(Boolean).join('；');details.append(summary,evidence);div.append(details);}$('detail-audit').append(div);}if(!events.length)$('detail-audit').textContent='初始化样本；暂无本会话操作';const a=actionFor(r);$('detail-action').hidden=!a;if(a){$('detail-action').textContent=a[1];$('detail-action').onclick=()=>{ $('detail-dialog').close();openAction(r,a);};}$('detail-readonly').textContent=!a?(r.executorId===Eam.s.person?'需切换至独立授权复核人员，执行人不能自验。':'当前状态或权限不提供修改操作。'):'';$('detail-create-work').hidden=kind==='discoveries'||r.status==='closed'||!canManage();if($('detail-archive')){$('detail-archive').hidden=kind!=='discoveries'||!canManage()||!['submitted','triaged'].includes(r.status);$('detail-archive').onclick=()=>{$('detail-dialog').close();openAction(r,['archive','核实并归档']);};}$('detail-create-work').onclick=()=>Eam.go('order-list',{create:'1',problemKind:kind,problemId:r.id});$('detail-equipment').onclick=()=>Eam.go('device',{equipment:r.equipmentId,tab:'overview'});$('detail-dialog').showModal();}catch(e){Eam.message(e.message);}}
async function openAction(row,a){if(busy)return;const t=++actionToken;$('load-status').textContent='正在读取'+a[1]+'表单…';try{const target=await api.request('GET','/'+kind+'/'+row.id);if(t!==actionToken)return;EamArchiveContext.assertRecord(target,location.search);current=target;actionTarget=JSON.parse(JSON.stringify(target));currentAction=a[0];$('action-form').reset();$('action-title').textContent=a[1];$('action-context').textContent=current.id+' · '+current.description+' · 版本 '+current.version;$('triage-fields').hidden=currentAction!=='triage';$('restore-field').hidden=currentAction!=='restore';$('decision-field').hidden=currentAction!=='verify';$('evidence-field').hidden=currentAction==='triage';$('action-evidence').required=currentAction!=='triage';$('triage-due').required=currentAction==='triage';$('restore-time').required=currentAction==='restore';$('action-error').textContent='';if(currentAction==='triage'){const result=await api.request('GET','/defects');$('existing-defect').replaceChildren(new Option('不关联',''));for(const r of result.rows.filter(r=>r.equipmentId===current.equipmentId&&r.status!=='closed'))$('existing-defect').add(new Option(r.id+' '+r.description,r.id));}if(currentAction==='triage'&&['defects','failures','hazards'].includes(preferred))$({'defects':'triage-defect','failures':'triage-failure','hazards':'triage-hazard'}[preferred]).checked=true;if(currentAction==='archive')$('action-title').textContent='核实并归档（不会关闭关联问题）';$('action-submit').textContent=currentAction==='archive'?'确认归档':currentAction==='triage'?'确认分诊并生成关联问题':'确认提交';$('action-dialog').showModal();$('load-status').textContent='已打开 '+current.id+' 的'+a[1]+'表单';}catch(e){Eam.message(e.message);}}
$('action-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('action-submit').disabled=true;$('action-error').textContent='';const body={expectedVersion:actionTarget.version,reason:$('action-reason').value,evidence:$('action-evidence').value,decision:$('verify-decision').value,restoredAt:$('restore-time').value};if(currentAction==='triage')Object.assign(body,{types:[...($('triage-defect').checked?['defects']:[]),...($('triage-failure').checked?['failures']:[]),...($('triage-hazard').checked?['hazards']:[])],ownerId:$('triage-owner').value,dueAt:$('triage-due').value,existingId:$('existing-defect').value,failureMode:$('failure-mode').value,impact:$('failure-impact').value});try{await api.request('POST','/'+kind+'/'+actionTarget.id+'/'+currentAction,body);$('action-dialog').close();await load();Eam.message('已保存；其他问题、工单和专业限制不会自动关闭');}catch(error){$('action-error').textContent=error.message+'；输入已保留。取消后刷新可重新读取当前版本。';}finally{busy=false;$('action-submit').disabled=false;}};
$('create-discovery').disabled=!['operator','inspector','technician','engineer','supervisor','safety'].includes(Eam.s.role);$('create-discovery').title=$('create-discovery').disabled?'当前角色没有异常提交权限':'';
let submitKey='';$('create-discovery').onclick=()=>{if(kind!=='discoveries'){Eam.go('abnormal-events',{create:'1',problemKind:kind});return;}$('create-form').reset();$('create-equipment').value=new URLSearchParams(location.search).get('equipment')||$('create-equipment').value;const now=new Date();$('create-time').value=new Date(now-now.getTimezoneOffset()*60000).toISOString().slice(0,16);submitKey=crypto.randomUUID();$('create-error').textContent='';$('create-dialog').showModal();};$('create-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const submit=e.submitter;submit.disabled=true;try{const created=await api.request('POST','/discoveries',{idempotencyKey:submitKey,equipmentId:$('create-equipment').value,description:$('create-description').value,occurredAt:$('create-time').value,source:$('create-source').value,priority:$('create-priority').value,part:$('create-part').value,evidence:$('create-evidence').value,emergencyAction:$('create-emergency').value});$('create-dialog').close();await load();if(query.get('equipment')&&created.equipmentId!==query.get('equipment')){Eam.go('abnormal-events',{id:created.id,equipment:created.equipmentId});}else if(query.get('equipment')&&created.equipmentId!==query.get('equipment')){Eam.go('abnormal-events',{id:created.id,equipment:created.equipmentId});}else if(canManage()){busy=false;await openAction(created,['triage','核实分诊']);}else Eam.message('发现已提交，等待班组长或工程师核实分诊');}catch(error){$('create-error').textContent=error.message+'；输入已保留。';}finally{busy=false;submit.disabled=false;}};
$('detail-close').onclick=()=>$('detail-dialog').close();$('action-cancel').onclick=()=>$('action-dialog').close();$('create-cancel').onclick=()=>$('create-dialog').close();$('refresh').onclick=load;for(const id of ['search','status-filter','priority-filter','mine'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=1;draw();});$('clear-filter').onclick=()=>{for(const id of ['search','status-filter','priority-filter'])$(id).value='';$('mine').checked=false;page=1;draw();};$('previous').onclick=()=>{page--;draw();};$('next').onclick=()=>{page++;draw();};
try{equipment=(await api.request('GET','/equipment')).rows;people=(await api.request('GET','/people')).rows;for(const r of equipment)$('create-equipment').add(new Option(r.name+' / '+r.code,r.id));for(const p of people)$('triage-owner').add(new Option(p.name,p.id));const states=kind==='discoveries'?['submitted','triaged','archived','draft']:kind==='defects'?['open','in_progress','pending_verification','closed']:['confirmed','restored','closed'];for(const s of states)$('status-filter').add(new Option(labels[s],s));await load();if(query.get('id')){const selected=rows.find(r=>r.id===query.get('id'));if(query.get('action')==='triage'&&selected&&actionFor(selected)?.[0]==='triage')await openAction(selected,['triage','核实分诊']);else await openDetail(query.get('id'));}if(query.get('create'))$('create-discovery').click();}catch(e){$('load-status').textContent=e.message;EamUiComponents.setTableStatus('problem-rows','error',e.message,()=>location.reload());}
})();

});
